function birthInfo(s,p){if(p.birth)return;const c=L.country(s,p),u=hash(s.seed+'|'+p.id+'|sex');const maleRatio=105;p.sex=u<maleRatio/(100+maleRatio)?'M':'F';const pool=regionalNames[c.region]||regionalNames.Europe;if(p.age===0&&!p.memories.length)p.name=L.nameFor?L.nameFor(s,{country:p.country,origin:p.origin,sex:p.sex,role:'self',key:p.id}).given:pool[p.sex][Math.floor(hash(s.seed+'|'+p.id+'|name')*pool[p.sex].length)];const tier=p.wealthTier??.5,label=tier<.2?'Très modeste':tier<.4?'Modeste':tier<.6?'Intermédiaire':tier<.8?'Aisée':'Très aisée';const structure=hash(s.seed+'|'+p.id+'|foyer');p.birth={country:c.code,countryName:c.name,countryShare:c.births/L.worldDataset.totalBirths,sex:p.sex,sexProbability:p.sex==='M'?105/205:100/205,familyTier:label,familyProbability:.2,structure:structure<.72?'Deux adultes référents':structure<.9?'Un adulte référent':'Foyer avec famille élargie',siblings:Math.floor(hash(s.seed+'|'+p.id+'|siblings')*4),urban:p.urban,income:p.householdIncome,ratioSource:'Ratio de référence 105 garçons pour 100 filles (INED), appliqué uniformément ; pas un taux national mesuré.'}}
function normalize(s){if(!s)return s;base.ensure(s);s.clock??={fraction:0,speed:1};s.clock.fraction=L.clamp(Number(s.clock.fraction)||0,0,1.1);if(![1,2,4].includes(s.clock.speed))s.clock.speed=1;for(const p of Object.values(s.people)){if(p.country==='XX'){const n=hash(s.seed+'|'+p.id+'|legacy-country')*L.worldDataset.totalBirths;let t=0;const c=L.countries.find(c=>(t+=c.births)>n)||L.countries[0];p.country=c.code;p.origin=c.code;p.birth=null}birthInfo(s,p)}if(s.pending?.id==='birth'){s.pending.choices[0].fx={};s.pending.choices[0].label='Laisser mon histoire commencer';s.pending.choices[0].note='Chaque année compte. La frise avance à votre rythme.'}return s}
function create(seed,code,year){const s=base.create(seed,code,year);normalize(s);s.birthRevealed=false;L.log(s,`Le tirage vous donne ${s.person.birth.sex==='M'?'un garçon':'une fille'}, dans un foyer ${s.person.birth.familyTier.toLowerCase()} en ${s.person.birth.countryName}. Ces conditions sont un départ, pas une destinée.`,true,'birth');return s}
function yearMoments(s){normalize(s);if(s.moments?.year===s.year&&s.moments?.person===s.person.id)return s.moments;const p=s.person,a=p.age;let pool=[];
if(a<4)pool=[['Vous reconnaissez une voix familière et vous vous apaisez.',{happy:2}],['Une nuit agitée fatigue tout le foyer.',{energy:-2}],['Un proche vous fait rire pour la première fois de la journée.',{happy:2}],['Votre monde tient encore dans quelques visages, mais il s’agrandit.',{happy:1}],['Un petit rhume bouscule les habitudes. Vous récupérez.',{energy:-1}],['Un jeu tout simple devient un rituel dans votre famille.',{happy:2}]];
else if(a<13)pool=[['Un livre vous donne envie de comprendre comment les choses fonctionnent.',{academic:1}],['Vous passez un après-midi à inventer un jeu avec ce qui vous entoure.',{creative:1}],['Une remarque à l’école vous reste en tête plus longtemps que prévu.',{stress:2}],['Vous apprenez à faire quelque chose sans demander d’aide.',{technical:1}],['Une conversation familiale vous aide à mettre des mots sur une émotion.',{social:1}],['Une journée au grand air vous fait oublier les petites contrariétés.',{energy:2}],['Vous trouvez un coin tranquille qui devient un petit refuge.',{stress:-2}],['Une activité en groupe vous apprend à laisser aussi de la place aux autres.',{social:1}]];
else if(a<18)pool=[['Vous changez d’avis sur quelque chose que vous croyiez évident.',{academic:1}],['Une musique devient la bande-son de votre année.',{happy:2}],['Vous comparez votre vie à celle des autres, puis essayez de prendre du recul.',{stress:1}],['Vous osez poser une question que vous gardiez pour vous.',{social:1}],['Un projet personnel vous occupe bien après les cours.',{creative:1}],['Une petite réussite vous donne plus de confiance que prévu.',{happy:2}],['Vous apprenez que dire non peut aussi préserver une relation.',{social:1}]];
else pool=[['Vous découvrez un endroit où vous aimez revenir.',{happy:2}],['Une dépense imprévue vous rappelle l’utilité d’une réserve.',{stress:1}],['Vous apprenez une méthode qui rend une tâche quotidienne plus simple.',{management:1}],['Vous prenez une soirée sans rien prévoir. Cela fait du bien.',{energy:2}],['Une conversation remet doucement une certitude en question.',{academic:1}],['Vous remarquez que vos priorités ont changé sans grand événement.',{happy:1}],['Vous faites quelque chose pour le plaisir, sans chercher à être performant.',{creative:1}],['Un souvenir d’enfance revient au détour d’une journée ordinaire.',{happy:1}]];
if(p.career)pool.push([`Dans votre travail en ${L.sectors[p.career.sector].name.toLowerCase()}, vous trouvez une solution à un problème récurrent.`,{[L.sectors[p.career.sector].skill]:1}],[`Une semaine chargée au travail empiète sur votre repos.`,{energy:-2}]);
if(p.partner)pool.push([`Un moment simple avec ${p.partner.name} vous rappelle pourquoi vous aimez être ensemble.`,{happy:2,bond:1}],[`Vous et ${p.partner.name} n’avez pas tout à fait les mêmes envies pour le week-end. Vous en discutez.`,{social:1}]);
const liveChildren=p.children.filter(x=>x.alive!==false);if(liveChildren.length){const x=select(s,'child',liveChildren);pool.push([`${x.name} vous raconte quelque chose d’important dans sa journée.`,{happy:2}],[`Vous reconnaissez un peu de vous dans un geste de ${x.name}, puis beaucoup de sa propre personnalité.`,{happy:2}])}
const friends=p.friends.filter(x=>x.alive!==false);if(friends.length){const x=select(s,'friend',friends);pool.push([`Un message de ${x.name} vous fait sourire au milieu d’une journée banale.`,{happy:2}])}
if(p.projects.length){const x=select(s,'project',p.projects);pool.push([`Vous repensez à votre projet « ${x.name} ». La prochaine étape paraît un peu plus claire.`,{management:1}])}
if(a>65)pool.push(['Vous racontez une histoire de votre jeunesse, en remarquant ce que le temps y a changé.',{happy:2}],['Vous retrouvez du plaisir dans une habitude que vous aviez laissée de côté.',{energy:2}]);
const first=select(s,'moment-a',pool),remaining=pool.filter(x=>x!==first),second=select(s,'moment-b',remaining);s.moments={year:s.year,person:p.id,items:[{id:s.year+'-'+p.id+'-3',month:3,text:first[0],effects:first[1]},{id:s.year+'-'+p.id+'-8',month:8,text:second[0],effects:second[1]}],fired:[]};return s.moments}
function moment(s,id){const m=yearMoments(s),x=m.items.find(x=>x.id===id);if(!x||m.fired.includes(id)||!s.person.alive)return false;const p=s.person;for(const[k,n]of Object.entries(x.effects)){if(k==='bond'&&p.partner)p.partner.bond=L.clamp(p.partner.bond+n);else if(k in p.skills)p.skills[k]=L.clamp(p.skills[k]+n);else{const target={happy:'happiness',energy:'energy',stress:'stress',health:'health'}[k];if(target)p[target]=L.clamp(p[target]+n)}}L.log(s,x.text,false,'instant');const entry=s.journal[s.journal.length-1];entry.month=x.month;m.fired.push(id);return true}
function isImportant(s,e){if(!e)return false;if(e.required)return true;if(['birth','school','talent','teen','adult','turn30','turn50','retirement','burnout-warning','budget'].includes(e.id)||e.id.startsWith('project-')||e.id.startsWith('friend-return-'))return true;if(e.id==='couple-conflict'&&s.person.partner?.bond<35)return true;return hash(s.seed+'|'+s.person.id+'|'+s.year+'|decision')<(s.person.age<18?.6:.45)}
function year(s,withEvent=true){normalize(s);if(s.pending||!s.person.alive)return false;const moments=yearMoments(s);for(const x of moments.items)moment(s,x.id);const success=base.year(s,withEvent);if(!success)return false;s.clock.fraction=0;s.moments=null;if(s.person.alive){if(s.person.age<5&&!s.pending?.announce){s.pending=null}else if(s.pending&&!isImportant(s,s.pending)){L.log(s,s.pending.text,false,'ambiance');s.pending=null}yearMoments(s)}return true}
